public:
    int validSubarrays(vector<int>& nums) {
        vector<int> st;
        int res = 0, n = nums.size();
        for (int i = 0; i < n; ++i) {
            while (!st.empty() && nums[st.back()] > nums[i]) {
                int prev = st.back();
                st.pop_back();
                res += (i - prev);
            }
            st.push_back(i);
        }
        while (!st.empty()) {
            int prev = st.back();
            st.pop_back();
            res += (n - prev);
        }
